function npv(rate, init, flows){
  rate=(+rate); if(isNaN(rate)) return {error:'请输入折现率'};
  init=(+init); if(isNaN(init)) init=0;
  var arr=String(flows||'').trim().split(/[\s,;]+/).filter(function(x){return x.length;}).map(function(x){var v=+x; return isNaN(v)?0:v;});
  if(!arr.length) return {error:'请至少输入一期现金流'};
  var v=-init;
  for(var t=1;t<=arr.length;t++){ v+=arr[t-1]/Math.pow(1+rate,t); }
  v=Math.round(v*100)/100;
  return {npv:v, rate:rate, init:init, flows:arr, note: v>=0?'净现值为正（按该折现率可行）':'净现值为负（按该折现率不可行）'};
}
var EXPORTS={npv:npv};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NpvForgePure = EXPORTS; }
